2. Load the JSON content from the file into a dictionary.
3. Validate that all fields listed in the "required" section of the schema are present in the JSON data.
4. Iterate through the schema properties and verify that the data types of the corresponding fields in the JSON match the expected types.
5. Validate the email field against the provided regular expression pattern.
6. Check if the requested attribute exists in the JSON data and return its value, raising a ValueError if it is missing or if any validation step fails.

### code
```python
import json
import os
import re

def task_func(
    file_path,
    attribute,
    INPUT_JSON={
        "type": "object",
        "properties": {
            "name": {"type": str},  
            "age": {"type": int},   
            "email": {"type": str}  
        },
        "required": ["name", "age", "email"]
    },
    EMAIL_REGEX=r"^[a-z0-9]+[\._]?[a-z0-9]+[@]\w+[.]\w{2,3}$"):

    if not os.path.exists(file_path):
        raise ValueError("File does not exist")

    with open(file_path, 'r') as f:
        data = json.load(f)

    for field in INPUT_JSON.get("required", []):
        if field not in data:
            raise ValueError(f"Required attribute '{field}' is missing")

    properties = INPUT_JSON.get("properties", {})
    for key, config in properties.items():
        if key in data:
            if not isinstance(data[key], config["type"]):
                raise ValueError(f"Type mismatch for attribute '{key}'")

    if "email" in data:
        if not re.match(EMAIL_REGEX, str(data["email"])):
            raise ValueError("Invalid email format")

    if attribute not in data:
        raise ValueError(f"Attribute '{attribute}' not found in JSON")

    return data[attribute]
